interface Entry<T> {
  value: T;
  priority: number;
  seq: number;
}

export class PriorityQueue<T> {
  private entries: Entry<T>[] = [];
  private counter = 0;

  push(value: T, priority = 0): void {
    this.entries.push({ value, priority, seq: this.counter++ });
    this.entries.sort((a, b) => b.priority - a.priority || a.seq - b.seq);
  }

  shift(): T | undefined {
    return this.entries.shift()?.value;
  }

  get size(): number {
    return this.entries.length;
  }
}
